import { `@lf/email` as email, `@lf/attio` as attio } from adapters
import { acme } from credentials

inbox = connect email
crm   = connect attio using acme

function team_size(name: <text>, people: <{ name: text, manager: text }[]>): <number> {
  reports = filter(people, (p) => p.manager == name)
  return 1 + List.sum(map(reports, (r) => team_size(r.name, people)))
}

function `Intake`(m: <inbox-[:Email]->>) {
  people = [
    { name: "Ada",   manager: "" },
    { name: "Grace", manager: "Ada" },
    { name: "Alan",  manager: "Grace" },
  ]
  n = team_size("Ada", people)
  write crm-[:Companies]-> {
    unique by (Name)
    Name:        m.Subject
    Description: "a team of ${n}"
  }
}

