import { `@lf/manual` as manual } from adapters

runs = connect manual

node Company: "each company named in the supplied text" {
  name:    <text> "the company's name"
  website: <text | null> "its website, if given"
}

node Found {
  node companies {
    name:    <text>
    website: <text | null>
  }
}

function `Dedupe`(go: <runs-[:Invocation]->>) {
  deduped = graph<Found> {}

  map(extract([go.Text], Company), (c) => {
    write deduped-[:companies]-> {
      unique by (FUZZY name)
      name:      c.name
      website ?: c.website
    }
  })

  deduped-[c:companies ORDER BY c.name]-> {
    return c.name
  }
}

import { `@lf/email` as email, `@lf/attio` as attio } from adapters
import { acme } from credentials

inbox = connect email
crm   = connect attio using acme

node Message {
  Body: <text>
  node Attachments {
    Name: <text>
    `Content Type`: <text>
  }
}

node Setting {
  mode: <text | null>
  limit: <number | null>
}

function `Snapshot`(m: <inbox-[:Email]->>) {
  msg = graph<Message> {
    Body: m.Body
    Attachments: m-[a:Attachments]-> {
      Name: a.Name
      `Content Type`: a.`Content Type`
    }
  }
  copy = graph<Message> {
    Body: m.Body
    Attachments: m-[:Attachments]->
  }
  empty = graph<Setting> {}
  raw   = { mode: "fast", limit: 3 }
  cfg   = graph<Setting> { ...raw }
  loose = graph { title: m.Subject }
  msg-[a:Attachments]-> {
    write crm-[:Companies]-> { unique by (Name) Name: a.Name }
  }
}

