function `Label`(name: <text>, tags: <text[]>, cfg: <{ prefix: text, suffix?: text }>) {
  return "${cfg.prefix}${name} (${Text.join(tags, ", ")})"
}

function `Intake`(m: <inbox-[:Email]->>) {
  title = Label(m.Subject, ["new", "inbound"], { prefix: "> " })
  write crm-[:Companies]-> {
    unique by (Name)
    Name:        m.Subject
    Description: title
  }
}

import { `@lf/email` as email, `@lf/attio` as attio } from adapters
import { acme } from credentials

inbox = connect email
crm   = connect attio using acme

roster = [
  { Name: "Ada",   Theme: "Consumer" },
  { Name: "Grace", Theme: "Infra" },
  { Name: "Alan",  Theme: "Health" },
]

node Mention: "each company named, weighed against the team's own themes" {
  name: <text> "the company's name"
}

function `Match Mentions`(m: <inbox-[:Email]->>) {
  themes = Text.join(map(roster, (r) => "${r.Name} (${r.Theme})"), ", ")
  byName = List.keyBy(roster, (r) => r.Name)
  found  = extract([m.Body], Mention)

  owner = byName.Ada
  if (owner == null) { fail("no such teammate on the roster") }
  map(found, (c) => {
    write crm-[:Companies]-> { unique by (FUZZY Name), Name: c.name, Description ?: "flagged by ${owner.Name}; team themes: ${themes}" }
  })
}

import { `@lf/manual` as manual, `@lf/attio` as attio } from adapters
import { acme } from credentials

runs = connect manual
crm  = connect attio using acme

function `Roster`(go: <runs-[:Invocation]->>) {
  names  = crm-[p:People]-> { return p.Name }
  titles = crm-[p:People]-> { return { name: p.Name, title: p.`Job Title` } }
  ranked = sort(titles, (r) => r.title, { order: "desc" })
  write crm-[:Companies]-> {
    unique by (`Name`)
    Name: coalesce(first(sort(names)), "nobody")
    Description: "${count(ranked)} people, ${Text.join(sort(names), ", ")}"
  }
}

listen to runs {} fire `Roster`

