import { `@lf/email` as email, `@lf/attio` as attio } from adapters
import { acme } from credentials

inbox = connect email
crm   = connect attio using acme

function `Intake`(m: <inbox-[:Email]->>) {
  if (Text.regexExtract(m.Subject, "(DEAL-\\d+)") != null) {
    company = write crm-[:Companies]-> {
      Name:        Text.slug(m.Subject)
      Description: Currency.codeFromFigure(m.Body)
      `Team Size` ?: Number.parse(m.Body)
    }
    write company-[:Tasks]-> {
      Content:  "Follow up on ${m.Subject}"
      Deadline: Date.addDays(@current_date, 14)
    }
    write company-[:Notes]-> {
      Title:   "Received"
      Content: "${Date.from(@current_date)} / ${DateTime.from(m.Body)} / ${Date.format(@current_date, "MMMM D, YYYY")}"
    }
  }
}

